"""Decision-theoretic scaffold."""
from nodespec import N

N("loss_function", "definition", "decision_theory",
  "A loss function L(theta, a) >= 0 gives the cost of taking action a when the true parameter is theta; L(theta, theta) is usually 0.",
  parseable="L: Theta x A -> [0, inf)",
  symbols={"a": "an action / decision, type: element of the action space A (an estimate, or 'reject'/'accept')",
           "L(theta, a)": "the loss, type: nonnegative real"},
  tcn="A user-supplied function encoding the consequences of error. Squared error (theta - a)^2, absolute error |theta - a|, 0-1 loss 1{a != theta}, and the check (pinball) loss are the standard choices; the whole theory is relative to it.",
  spec=["estimation: A = Theta, L = (theta - a)^2 or |theta - a|",
        "testing: A = {0, 1}, L(theta, a) = 1{a wrongly rejects/accepts} -- possibly weighted by how wrong",
        "asymmetric: newsvendor loss L(theta, a) = c_o (a - theta)_+ + c_u (theta - a)_+ for over/under-stocking"],
  cxd={"loss_reflects_real_consequences": "using squared-error loss when the real cost is a step function (a dam either overtops or not) gives a Bayes rule optimizing the wrong thing"},
  misuse=["defaulting to squared-error loss without asking whether errors really cost the square of their size",
          "comparing procedures under one loss and deploying them where a different loss applies"],
  related={"required_by": ["risk_function", "bayes_estimator", "posterior_mean_rule"]},
  sources=["berger_statistical_decision_theory", "lehmann_casella_tpe"])

N("risk_function", "definition", "decision_theory",
  "The risk of a decision rule delta at theta is R(theta, delta) = E_theta[ L(theta, delta(X)) ]: the expected loss over repeated sampling under P_theta.",
  parseable="R(theta, delta) = E_theta[ L(theta, delta(X)) ]",
  symbols={"delta": "a decision rule, type: map data -> action",
           "R(., delta)": "the risk function, type: nonnegative function on Theta"},
  tcn="A frequentist average (over the data) of the loss, for each fixed theta. Two rules are compared by their whole risk FUNCTIONS -- which usually cross, so there is no universally best rule (hence admissibility, minimax, Bayes as ways to break the tie).",
  spec=["squared-error loss: R(theta, delta) = MSE(theta) = Var + bias^2",
        "0-1 loss in testing: R(theta, delta) = P_theta(wrong decision) -- the error probability",
        "the constant rule delta = c has R(theta) = L(theta, c), typically 0 at theta = c and large elsewhere"],
  cxd={"expectation_exists": "a rule whose loss has infinite expectation under some theta (an estimator with infinite MSE) has undefined risk there and cannot be compared by risk"},
  misuse=["summarizing a risk FUNCTION by a single number without saying how (max? average against which weight?) -- that choice IS the minimax-vs-Bayes decision",
          "comparing risks at the observed data's implied theta_hat rather than as functions"],
  related={"required_by": ["admissibility", "minimax_rule", "bayes_risk", "james_stein"],
           "specializes_to": ["mean_squared_error", "power_function"]},
  sources=["berger_statistical_decision_theory"])

N("decision_rule", "definition", "decision_theory",
  "A decision rule delta maps the data to an action: delta: X^n -> A. Estimators (A = Theta) and tests (A = {accept, reject}) are decision rules; a randomized rule maps data to a distribution over A.",
  parseable="delta: X^n -> A   (nonrandomized)   or   delta: X^n -> P(A)   (randomized)",
  symbols={"A": "the action space", "randomized delta": "outputs a probability distribution over actions (needed for exact-size tests on discrete data)"},
  tcn="The abstract object the whole theory optimizes. Placed AFTER estimator and test_function in the graph because those concrete instances motivate it (see conventions.md -- this is tsort order, not teaching order).",
  spec=["an estimator theta_hat(.) is a decision rule with A = Theta",
        "a test phi(.) in [0,1] is a randomized decision rule with A = {0,1}",
        "'always report 5' and 'flip a coin' are (bad) decision rules"],
  cxd={"measurable": "a non-measurable rule has no well-defined risk -- excluded"},
  misuse=["restricting attention to nonrandomized rules when an exact-size test on discrete data requires randomization",
          "conflating the rule (a function) with its output on one dataset"],
  related={"specializes_from": ["estimator", "test_function"], "required_by": ["risk_function"]},
  sources=["berger_statistical_decision_theory", "lehmann_romano_tsh"])

N("admissibility", "definition", "decision_theory",
  "A decision rule delta is admissible if no rule delta' has R(theta, delta') <= R(theta, delta) for all theta with strict inequality for some theta; otherwise delta is inadmissible (dominated).",
  parseable="delta admissible  <=>  no delta' with R(., delta') <= R(., delta) everywhere and < somewhere",
  symbols={"'delta' dominates delta'": "R(., delta') <= R(., delta) with strict somewhere -- a free lunch"},
  tcn="A minimal-competence criterion: an inadmissible rule can be strictly improved everywhere at no cost, so it should not be used. Admissibility does NOT single out a good rule (silly rules like delta = c are often admissible).",
  spec=["Xbar is admissible for a 1- or 2-dimensional normal mean under squared-error loss",
        "every unique Bayes rule is admissible; a Bayes rule with continuous risk is admissible",
        "a constant estimator delta = c is admissible (nothing beats it at theta = c) -- admissibility alone is weak"],
  cxd={"dimension": "Xbar is INADMISSIBLE for a normal mean in dimension d >= 3 -- the James-Stein estimator dominates it everywhere (james_stein). This is the famous Stein paradox."},
  misuse=["treating admissibility as a strong endorsement -- it rules out the obviously-wasteful, nothing more",
          "assuming the MLE / UMVUE is admissible -- it often is not in multiparameter problems"],
  related={"required_by": ["complete_class", "james_stein"], "uses": ["risk_function"]},
  sources=["berger_statistical_decision_theory", "lehmann_casella_tpe"])

N("minimax_rule", "definition", "decision_theory",
  "A rule delta* is minimax if it minimizes the worst-case risk: sup_theta R(theta, delta*) = inf_delta sup_theta R(theta, delta).",
  parseable="delta* in argmin_delta  sup_{theta in Theta}  R(theta, delta)",
  symbols={"sup_theta R(theta, delta)": "the maximum risk of delta -- its worst case over Theta"},
  tcn="The rule with the best guarantee against an adversarial Nature. Often found as a Bayes rule against a 'least favorable' prior (the prior that makes the Bayes risk largest); minimax = Bayes vs least-favorable prior when a saddle point exists.",
  spec=["N(theta, 1) known variance, Theta = R: Xbar is minimax (constant risk 1/n, and it is Bayes vs the flat improper prior limit)",
        "Bernoulli(p), Theta = [0,1], squared-error loss: the minimax estimator is (sum X_i + sqrt(n)/2) / (n + sqrt(n)) -- a Beta(sqrt(n)/2, sqrt(n)/2) Bayes rule, with constant risk",
        "bounded normal mean |theta| <= tau: the minimax rule is nonlinear and shrinks toward 0"],
  cxd={"Theta_bounded_or_risk_controlled": "if Theta is unbounded and risk is unbounded, sup_theta R can be infinite for every rule and 'minimax' is degenerate -- restrict Theta or the loss"},
  misuse=["choosing minimax when the worst case is implausible -- it can be very conservative, paying everywhere to protect against a corner of Theta",
          "assuming the minimax rule has constant risk -- it need not, though many do"],
  related={"uses": ["risk_function", "bayes_risk"], "commonly_confused_with": ["local_asymptotic_minimax"]},
  sources=["berger_statistical_decision_theory", "lehmann_casella_tpe"])

N("bayes_risk", "definition", "decision_theory",
  "The Bayes risk of a rule delta under a prior pi is r(pi, delta) = int R(theta, delta) pi(dtheta) = E_pi E_theta[ L(theta, delta(X)) ]: the risk averaged over theta with weight pi.",
  parseable="r(pi, delta) = int_Theta R(theta, delta) pi(dtheta)",
  symbols={"pi": "the prior (a probability measure on Theta, or an improper measure with finite r)",
           "r(pi, delta)": "a single number -- so Bayes risk TOTALLY orders the rules (unlike the risk function)"},
  tcn="A scalar summary of the risk function against a weighting pi. Minimizing it is what makes the Bayes rule well-defined and unique (a.s.). Different priors give different orderings.",
  regime="bayesian",
  spec=["r(pi, delta) = E_X[ posterior expected loss at X ] -- the two-way expectation can be taken in either order (Fubini)",
        "the minimizer over delta is delta_pi, the Bayes rule (posterior-loss minimizer)",
        "sup_pi inf_delta r(pi, delta) = the minimax risk when a saddle point exists (minimax theorem)"],
  cxd={"prior_proper_or_r_finite": "an improper prior with infinite Bayes risk gives no minimizer; 'generalized Bayes' rules (formal posterior mean) may still be admissible but are not Bayes in this sense"},
  misuse=["comparing Bayes risks computed under different priors as if on the same scale",
          "reporting the Bayes risk as the actual error -- it is an average over a hypothetical prior draw of theta"],
  related={"required_by": ["bayes_rule_minimizes_bayes_risk"], "uses": ["risk_function"]},
  sources=["berger_statistical_decision_theory"])

N("bayes_rule_minimizes_bayes_risk", "theorem", "decision_theory",
  "The rule that minimizes the posterior expected loss for each x, delta_pi(x) = argmin_a E[L(theta, a) | X = x], also minimizes the overall Bayes risk r(pi, delta); so the Bayes estimator is optimal against its prior.",
  parseable="delta_pi(x) := argmin_a E[L(theta,a)|x]   =>   r(pi, delta_pi) = inf_delta r(pi, delta)",
  symbols={"the pointwise-vs-global equivalence": "minimize under the integral sign"},
  tcn="Proof: r(pi, delta) = E_X[ E_{theta|X}[ L(theta, delta(X)) ] ] (Fubini/tower). The inner expectation is minimized, for each x separately, by delta(x) = delta_pi(x); a rule minimizing every inner term minimizes the outer average.",
  regime="bayesian",
  hyps=[],
  proof=("write the Bayes risk as an iterated expectation (tower property), then minimize the inner posterior expectation pointwise in x",
         "prob_tower_property", "core",
         "validation/proof-checks.lean Stat.bayes_rule_pointwise -- if g(x, a) >= g(x, a*(x)) for every a then E_X[g(X, delta(X))] >= E_X[g(X, a*(X))]; the interchange of min and integral"),
  spec=["squared-error loss => delta_pi = posterior mean (posterior_mean_rule)",
        "absolute loss => posterior median; 0-1 loss => posterior mode",
        "the theorem is what licenses 'just compute the posterior and summarize it' as an optimal procedure"],
  cxd={"inner_min_attained": "if argmin_a E[L(theta,a)|x] is empty (loss not lower-semicontinuous, or infinite everywhere) there is no Bayes rule -- e.g. squared loss with a Cauchy posterior"},
  misuse=["assuming the Bayes rule is also good in a frequentist sense for a fixed theta -- it is optimal ON AVERAGE against pi, and can be poor at a particular theta the prior disfavors",
          "forgetting the optimality is relative to the (subjective) prior"],
  related={"required_by": ["bayes_estimator"], "uses": ["bayes_risk", "posterior_mean_rule"]},
  sources=["berger_statistical_decision_theory", "robert_bayesian_choice"])

N("complete_class", "theorem", "decision_theory",
  "A class C of decision rules is complete if for every rule not in C there is a rule in C that dominates it. Under convexity of the loss and compactness/continuity conditions, the Bayes rules (together with their pointwise limits, the 'generalized Bayes' rules) form a complete class; every admissible rule is a (generalized) Bayes rule.",
  parseable="under regularity:  { admissible rules } subset closure( { Bayes rules } )",
  symbols={"complete class": "a set of rules you can restrict to without loss",
           "essentially complete": "the weaker 'dominate or tie' version"},
  tcn="A structural result reducing the search for a good rule to the Bayes rules. The precise hypotheses (compact Theta, continuous risk, convex loss -- Wald / Le Cam) are technical; this capsule states the theorem and cites the proof.",
  regime="exact",
  hyps=[],
  proof=("Wald's complete class theorem / Le Cam; separating-hyperplane arguments on the risk set",
         "bayes_rule_minimizes_bayes_risk", "cited",
         "CITED -- Wald 1950; Ferguson Mathematical Statistics Ch. 2; Le Cam. Not formalized."),
  spec=["consequence: if you want an admissible rule, look among (generalized) Bayes rules -- e.g. James-Stein is a generalized (empirical) Bayes rule",
        "in the normal-mean problem the admissible estimators are exactly the generalized Bayes ones (Brown 1971)",
        "for one-sided testing, the complete class is the set of monotone tests (Karlin-Rubin's structural half)"],
  cxd={"convex_loss_compact_Theta": "without convexity of the loss, randomized rules can be admissible and not Bayes; without compactness the closure operation is essential and 'generalized Bayes' rules that are not proper Bayes appear (Xbar itself is one)"},
  misuse=["reading it as 'only use Bayes rules' -- generalized/limiting Bayes rules are included, and these can look nothing like a posterior summary",
          "assuming the frequentist-optimal rule is a PROPER Bayes rule"],
  related={"uses": ["admissibility", "bayes_rule_minimizes_bayes_risk"]},
  sources=["ferguson_mathematical_statistics", "berger_statistical_decision_theory", "brown_1971"])

N("james_stein", "counterexample", "decision_theory",
  "For X ~ N(theta, I_d) with d >= 3, the estimator theta_hat_JS = (1 - (d - 2)/||X||^2) X has strictly smaller total squared-error risk E||theta_hat - theta||^2 than the MLE theta_hat = X for EVERY theta. Hence X (the MLE, UMVUE, and minimax estimator) is inadmissible in dimension >= 3.",
  parseable="d >= 3:  E_theta || theta_hat_JS - theta ||^2  <  E_theta || X - theta ||^2  = d,  for all theta",
  symbols={"theta_hat_JS": "the James-Stein shrinkage estimator",
           "(d - 2)/||X||^2": "the data-driven shrinkage factor -- shrinks X toward 0 (or toward any fixed point, or a subspace)",
           "d": "the dimension; the effect is absent for d <= 2"},
  tcn="A domination statement (a counterexample to admissibility of the MLE). Proof: Stein's unbiased risk estimate (SURE) gives E||theta_hat_JS - theta||^2 = d - E[(d-2)^2/||X||^2] < d. The (d-2) requires d >= 3 for the correction to help.",
  status_label="counterexample",
  regime="exact",
  hyps=[],
  proof=("Stein's identity E[(X - theta) g(X)] = E[g'(X)] gives an unbiased estimate of the risk difference, which is negative for d >= 3",
         "mse_bias_variance_decomposition", "cited",
         "CITED -- James-Stein 1961; Stein 1981 (SURE). The d=1 non-improvement and the risk-difference algebra are checked numerically in instance-checks.bc."),
  spec=["d = 1, 2: no estimator dominates X -- shrinkage cannot uniformly help (the (d-2) factor is <= 0)",
        "the positive-part James-Stein max(0, 1 - (d-2)/||X||^2) X dominates the raw JS and is closer to admissible (still not admissible)",
        "shrinkage toward the grand mean, or toward a regression fit, works too -- the target is arbitrary"],
  cxd={"d_at_least_3": "in d <= 2, X IS admissible -- the paradox is genuinely a high-dimensional phenomenon",
       "the_loss_is_TOTAL_squared_error": "James-Stein improves the SUM of squared errors; a single coordinate's MSE can get WORSE. If you care about one coordinate, shrinkage can hurt you."},
  misuse=["shrinking when you only care about one of the d parameters -- the improvement is in the aggregate, possibly at that coordinate's expense",
          "reading it as 'the MLE is bad' -- its total risk is d and JS's is only modestly less at most theta; the point is the EXISTENCE of uniform domination, overturning the sufficiency of unbiasedness/minimaxity"],
  apps=["empirical-Bayes shrinkage in genomics (limma / moderated t-statistics shrink thousands of gene-wise variances toward a common value), sports analytics (regress batting averages to the mean), and small-area estimation (Fay-Herriot) -- all are James-Stein in spirit",
        "the theoretical seed of ridge regression, LASSO, and every regularized high-dimensional estimator"],
  related={"illustrated_by": ["prob_normal"], "commonly_confused_with": ["admissibility"],
           "historically_precedes": ["hastie_tibshirani_friedman_esl"]},
  sources=["james_stein_1961", "stein_1981", "efron_large_scale_inference"])
